#include <iostream>
#include <vector>
#include <string>
using namespace std;
int main(){
    ios_base::sync_with_stdio(false); cin.tie(NULL);
    string s; cin >> s;
    int n = s.size();
    vector<int> P(n, 0);
    int c=0, r=0;
    for(int i=0;i<n;i++){
        int mirror = 2*c-i;
        if(i<r) P[i]=min(r-i, P[mirror]);
        while(i-P[i]-1>=0 && i+P[i]+1<n && s[i-P[i]-1]==s[i+P[i]+1]) P[i]++;
        if(i+P[i]>r){ c=i; r=i+P[i]; }
    }
    int q; cin>>q;
    while(q--){ int ci; cin>>ci; cout<<2*P[ci]+1<<"\n"; }
    return 0;
}

