import java.util.*;
import java.io.*;
public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int n = s.length();
        int[] P = new int[n];
        int c=0,r=0;
        for(int i=0;i<n;i++){
            int mirror=2*c-i;
            if(i<r) P[i]=Math.min(r-i,P[mirror]);
            while(i-P[i]-1>=0 && i+P[i]+1<n && s.charAt(i-P[i]-1)==s.charAt(i+P[i]+1)) P[i]++;
            if(i+P[i]>r){c=i;r=i+P[i];}
        }
        int q=Integer.parseInt(br.readLine().trim());
        StringBuilder sb=new StringBuilder();
        for(int i=0;i<q;i++){
            int ci=Integer.parseInt(br.readLine().trim());
            sb.append(2*P[ci]+1).append('\n');
        }
        System.out.print(sb);
    }
}
